package com.notificationservice.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="support_attachments")
public class SupportAttachmentEntity { @Id private UUID id; @Column(name="message_id",nullable=false) private UUID messageId; @Column(nullable=false,length=24) private String type; @Column(name="file_name",nullable=false,length=255) private String fileName; @Column(name="content_type",nullable=false,length=80) private String contentType; @Column(name="file_size",nullable=false) private long fileSize; @Column(nullable=false,length=1200) private String url; @Column(name="public_id",length=500) private String publicId; @Column(name="created_at",nullable=false) private Instant createdAt;
 public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getMessageId(){return messageId;} public void setMessageId(UUID v){messageId=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getFileName(){return fileName;} public void setFileName(String v){fileName=v;} public String getContentType(){return contentType;} public void setContentType(String v){contentType=v;} public long getFileSize(){return fileSize;} public void setFileSize(long v){fileSize=v;} public String getUrl(){return url;} public void setUrl(String v){url=v;} public String getPublicId(){return publicId;} public void setPublicId(String v){publicId=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;}}
